export const dynamic='force-dynamic';export const runtime='nodejs';
async function proxy(request,{params}){const {path}=await params;if(!['chat','history','expected'].includes(path.join('/')))return new Response('Not found',{status:404});const controller=new AbortController();const abort=()=>controller.abort();request.signal.addEventListener('abort',abort,{once:true});let reader;try{const upstream=await fetch('http://127.0.0.1:4191/api/'+path.join('/')+new URL(request.url).search,{method:request.method,headers:{'content-type':'application/json'},...(request.method==='POST'?{body:await request.text()}:{}),signal:controller.signal,cache:'no-store'});reader=upstream.body.getReader();const body=new ReadableStream({async pull(output){try{const next=await reader.read();if(next.done){request.signal.removeEventListener('abort',abort);output.close()}else output.enqueue(next.value)}catch(e){output.error(e)}},async cancel(reason){controller.abort();request.signal.removeEventListener('abort',abort);await reader.cancel(reason).catch(()=>{})}});return new Response(body,{status:upstream.status,headers:{'content-type':upstream.headers.get('content-type')||'application/json','cache-control':'no-store'}})}catch(e){request.signal.removeEventListener('abort',abort);controller.abort();return new Response('Proxy request aborted or failed',{status:502})}}
export const GET=proxy;export const POST=proxy;
